/* Scroll-triggered reveals (see src/components/Reveal.jsx) */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition:
    opacity 0.7s ease-out,
    transform 0.7s ease-out;
  will-change: opacity, transform;
}

.reveal-visible {
  opacity: 1;
